// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    NewIntelTechMedia c;
    function setUp() public { c = new NewIntelTechMedia(); }

    function testFuzz_property(address actor) public {
        // The owner of c is the deployer, i.e. this test contract (owner = msg.sender in C's constructor).
        // Only non-owner callers are admissible here: for them the owner-only NETM() must revert.
        vm.assume(actor != address(this));
        vm.assume(actor != address(0));

        vm.prank(actor);
        bool ok;
        try c.NETM() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a non-owner can never execute NETM(); the reference always reverts here,
        // while the mutant (owner modifier removed) succeeds and mints totalDistributed to the caller.
        assertTrue(!ok, "non-owner must not be able to execute NETM()");
    }
}
